<section class="detail-section episode-section" id="episoade"><div class="section-head"><div><span class="section-kicker">Următorul capitol</span><h2>Sezoane și episoade</h2></div><label class="season-selector">Sezon<select id="seasonSelect" aria-label="Alege sezonul"><?php foreach($seasons as $i=>$season):?><option value="season-<?=$i?>"<?=(int)($season['season']??0)===$firstSeason?' selected':''?>>Sezonul <?=(int)($season['season']??0)?> · <?=count((array)($season['episodes_data']??[]))?> episoade</option><?php endforeach;?></select></label></div>
<?php foreach($seasons as $i=>$season):$sn=(int)($season['season']??0);?><section class="season-panel" id="season-<?=$i?>" data-season="<?=$sn?>"<?=$sn!==$firstSeason?' hidden':''?> aria-label="Sezonul <?=$sn?>"><h3 class="visually-hidden">Sezonul <?=$sn?></h3><div class="episode-grid"><?php foreach((array)($season['episodes_data']??[]) as $ep):$en=(int)($ep['episode']??1);$epTitle=$ep['title']??'Episodul '.$en;?><article class="episode" data-episode-key="<?=e($titleItem['imdb_id'].':'.$sn.':'.$en)?>"><button class="episode-media js-play" type="button" data-player="<?=e(player_url($titleItem,$sn,$en))?>" data-title="<?=e(title_name($titleItem).' · S'.$sn.' · E'.$en)?>" data-id="<?=e($titleItem['imdb_id'])?>" data-season="<?=$sn?>" data-episode="<?=$en?>" aria-label="Redă episodul <?=$en?>: <?=e($epTitle)?>"><img referrerpolicy="no-referrer" src="<?=e(media_url($titleItem,'episode',$sn,$en))?>" alt="" width="480" height="270" loading="lazy" decoding="async" data-fallback="<?=e(item_background_url($titleItem))?>"><span class="episode-play"><?=icon('play')?></span><span class="episode-index">S<?=$sn?> · E<?=$en?></span></button><div class="episode-content"><div class="episode-top"><span>Episodul <?=$en?></span><span><?php if(!empty($ep['runtime'])):?><?=e(compact_duration($ep['runtime']))?><?php elseif(!empty($titleItem['runtime'])):?>≈ <?=e(compact_duration($titleItem['runtime']))?><?php endif;?><?php if(!empty($ep['rating'])):?> · IMDb ★ <?=e(number_format((float)$ep['rating'],1,',',''))?><?php endif;?></span></div><h3 class="episode-title"><?=e($epTitle)?></h3><?php if(!empty($ep['description'])||!empty($ep['overview'])):?><p class="episode-description"><?=e($ep['description']??$ep['overview'])?></p><?php endif;?><div class="episode-progress" hidden><progress max="100" value="0" aria-label="Progres episod"></progress><small></small></div><button class="text-btn js-play" type="button" data-player="<?=e(player_url($titleItem,$sn,$en))?>" data-title="<?=e(title_name($titleItem).' · S'.$sn.' · E'.$en)?>" data-id="<?=e($titleItem['imdb_id'])?>" data-season="<?=$sn?>" data-episode="<?=$en?>"><?=icon('play')?> <span data-episode-label>Redă episodul</span></button></div></article><?php endforeach;?></div></section><?php endforeach;?></section>
